    "year": 2009,
    "duration": 315,
    "quote": "他们以为我们想要的只不过是他们轻而易举所拥有的，我想在死之前回到家乡。",
    "lyrics": "这个城市已经死了\n这个夏天也死了\n我们走在街上，遇到的是一群死人\n和另一群死人\n而他们看起来就像活着一样\n家乡的小麦熟了\n家乡的人老了\n他们看着我，有时候就像没有看着一样\n而年轻人都去了城市\n年轻人都去了工厂\n有时候我觉得我死了\n有时候我觉得我老了\n有时候我看着疲软的身体却无法把我们的过去想起\n有时候我觉得我疯了\n有时候我觉得我还活着\n而所有来来往往的一切就像一条孤独的鲫鱼\n就像一条孤独的鲫鱼\n城里的人不知道什么是自由\n城里的人不知道什么是爱\n他们以为我们想要的只不过是他们轻而易举所拥有的\n我想在死之前回到家乡\n我想在老之前和他们在一起\n我罪孽、激荡、沉重、哀怨的一生必须埋在家乡\n大雨就要来了\n夹杂你柔软的身体和动人的故事\n而这一切却再也无法将我打动\n一片死寂的天空\n一片死寂的天空\n一片死寂的天空\n死寂的天空\n哎...\n昨天，一个陌生人问我\n嘿，朋友，你的家在哪里\n这个问题把我难住了\n你知道我离家太久\n让我想一想我的童年和家乡\n让我想一想我的爹和娘\n让我再想一想我的过去和家乡\n让我想一想我的爹和娘",
    "cover": "covers/cov_42088.jpg",
    "category": "live",
    "city": null,
    "era": "era_04_09",
    "channel_url": "https://t.me/libimusic/866",
