    "duration": 277,
    "quote": "我的眼睛是个秘密，我的头发是个秘密，我的身体是个秘密。",
    "lyrics": "沉默的你 阳光萧瑟的树林\n那些你爱的人 温柔的那么柔软\n无知的我 是落叶落魄又落魄\n曾经幻灭的岁月 穿插沉默的现在\n呼啸而过的青春 沉默不语的你\n即使给我个灿烂明天 让我忏悔的你\n这被禁忌的游戏 早已忘记的岁月\n这被禁忌的游戏 一如既往的岁月\n随风飘荡的我们 黑夜里寻找一点点欢愉\n再次面对这春色 失落的不知所以\n暗自叹息又暗自伤心 游戏已如此陌生\n看往川流的人群 穿越沉默的现在\n呼啸而过的青春 沉默不语的你\n即使给我个灿烂明天 让我忏悔的你\n这被禁忌的游戏 早已忘记了岁月\n这被禁忌的游戏 一如既往的岁月\n这被禁忌的游戏 早已忘记了岁月\n这被禁忌的游戏 一如既往的岁月\n你看荒谬的我们 离开禁忌的游戏",
    "cover": "covers/cov_42088.jpg",
    "category": "live",
    "city": null,
    "era": "era_04_09",
