    "quote": "命运来了，它带着天平给每个人算命。",
    "lyrics": "爱情来了\n她穿过夜色来看望一个人\n那不是我 是我的兄弟\n她背对着我脱下淋湿的衣服\n我看见外面两只喜鹊在打架\n我系进着鞋带冲进这夜色 夜色在唱 在唱\n来来来 ...\n理想来了\n它是个被母亲遗弃的小孩\n有一双结实的大腿蹦蹦跳跳到处乱跑\n我的兄弟曾经那么疯狂的爱着它 跟随着它\n不知道什么时候兄弟偷偷哭泣 要放弃它 于是唱\n来来来 ...\n命运来了\n它带着天平给每个人算命\n我看着它 睡着了\n我曾经那么无知的鄙视它 诅咒它\n如今我跪倒着苛求个机会 它看着我笑了 于是我唱\n来来 ...\n不管曾经或是以后\n拥有是什么\n请你相信我 我还会唱歌\n或许生死 或许悲观 离别是什么\n亲爱的兄弟 我还会唱歌\n不管永远 或是现在 会有些什么\n请你相信我 我还会唱歌\n来来来 ....",
