    "lyrics": "你像我见过的那个少年，背着青春走在九月的街头\n一阵风吹乱了我的头发，突然天气变得如此哀怨\n只不过是一场生活，只不过是一场生活\n只不过是一场生活，只不过是一场生活\n他举着新鲜的花圈在路口，等待人们给他穿越的信号\n阿姨迅速地转移了她的目光，你像个画像定格在中央\n只不过是一场命运，只不过是一场命运\n只不过是一场命运，只不过是一场命运\n我想给你三万收买这婚姻，和那个陌生的女人虚度这时光\n一个电话打出了我的眼泪，往事涌上心头青春就散场\n只不过是一场游戏，只不过是一场游戏\n只不过是一场游戏，只不过是一场游戏",
