    "duration": 249,
    "quote": "她的明亮她的晴朗，把无知化解成无聊的笑，寂静从潮湿处涌来，在处女和荡妇间周转。",
    "lyrics": "她睁着朦胧的眼睛，带着疲惫慢慢地靠近\n她的微笑她的味道，从身体里发出暗淡的光\n她陷入怀疑的恐惧，对着镜子假装在哭泣\n她的疯狂她的迷茫，她说现在她还不太想，被他们慢慢地忘掉\n嘞嘞嘞……她要在阳光下，拼命地奔跑\n嘞嘞嘞……她要在空虚里，拼命地舞蹈\n她交替黑色的双腿，向着嘈杂虚无地喷发\n她的明亮她的晴朗，把无知化解成无聊的笑\n寂静从潮湿处涌来，在处女和荡妇间周转\n她的分裂她的错觉，她说不如从现在开始，像苹果一样地烂掉\n嘞嘞嘞……她要在阳光下，拼命地奔跑\n嘞嘞嘞……她要在恐惧里，拼命地舞蹈\n嘞嘞嘞……她要在阳光下，拼命地奔跑\n嘞嘞嘞……她要在迷惑里，拼命地舞蹈",
