    "quote": "却又心甘情愿地失去了她，寂静隐约传来，像高原上的芬芳。",
    "lyrics": "表妹，你给我写信的时候我正在昆明\n正在等待高原的阳光\n从来没有想过你曾经的生活\n会在今天晚上超越了我\n你是否已经去过黄昏的海边\n在荒野和暖风里把自己谋杀\n原谅我吧表妹，爱人她在南京\n在那张传统的床上想我\n我用剩余的时间拼命安慰我自己\n却又心甘情愿地失去了她\n寂静隐约传来，像高原上的芬芳\n这芬芳让我无法对她去歌唱\n如果你感到被伤害，快乐总是不存在\n人们总是忽慢忽快地离开\n那就出发吧，穿上那件黑衬衫\n我想夜是个成熟的女人\n糜烂的心，飘了很远\n支持独立原创音乐，如果你喜欢\n你可以自由出价完成购买或捐赠",
