    "year": 2011,
    "duration": 386,
    "quote": "推开这扇门，是一片荒野；关上这扇门，也是一片荒野。",
    "lyrics": "总在这种时候，感觉自己已经飞的太远\n路灯全都灭了，不能破坏别人的幸福\n从没见过的细胞，睡衣和行星\n还有趴在玻璃上的灵魂\n它让我的心凉了又热了\n它说生生死死的爱恋又能如何\n相信吧，相信我们曾经恐惧的一切\n相信吧，门开了\n相信吧，相信我们曾经无奈的岁月\n门开了，它来了\n有时欣喜若狂，有时感觉不到生长\n黑暗里的秘密，你天生的美丽\n孤独来自脆弱的敏感\n敏感无法把美丽看穿\n相信吧，相信轰轰烈烈是你的未来\n相信吧，门开了\n相信吧，相信反反复复是我们情怀\n门开了，它来了",
