    "lyrics": "🎵 **《他们》**\n有人在哭泣，有人在歌唱，有人生来有钱包\n有人在奋斗，有人在幻想，有人一生没吃饱\n他们指向左，他们指向右，他们买了壮阳药\n我们不能说，我们不能做，我们的生活多美好\n有人在哭泣，有人在歌唱，有人生来有钱包\n有人在奋斗，有人在幻想，有人一生没吃饱\n他们指向左，他们指向右，他们买了壮阳药\n我们不能说，我们不能做，我们的生活多美好\n他们指向左，他们指向右，他们买了壮阳药\n我们不能说，我们不能做，我们的生活多美好\n\n━━━━━━━━━━━━━━━━━━━━━\n\n🎵 **《新年好呀》**\n新年好呀 新年好呀\n祝贺大家新年好\n我们唱歌 我们跳舞\n祝贺大家新年好",
