    "duration": 335,
    "quote": "嘞嘞嘞……她要在迷惑里，拼命地舞蹈，━━━━━━━━━━━━━━━━━━━━━。",
    "lyrics": "🎵 **《她》**\n她睁着朦胧的眼睛，带着疲惫慢慢地靠近\n她的微笑她的味道，从身体里发出暗淡的光\n她陷入怀疑的恐惧，对着镜子假装在哭泣\n她的疯狂她的迷茫，她说现在她还不太想，被他们慢慢地忘掉\n嘞嘞嘞……她要在阳光下，拼命地奔跑\n嘞嘞嘞……她要在空虚里，拼命地舞蹈\n她交替黑色的双腿，向着嘈杂虚无地喷发\n她的明亮她的晴朗，把无知化解成无聊的笑\n寂静从潮湿处涌来，在处女和荡妇间周转\n她的分裂她的错觉，她说不如从现在开始，像苹果一样地烂掉\n嘞嘞嘞……她要在阳光下，拼命地奔跑\n嘞嘞嘞……她要在恐惧里，拼命地舞蹈\n嘞嘞嘞……她要在阳光下，拼命地奔跑\n嘞嘞嘞……她要在迷惑里，拼命地舞蹈\n\n━━━━━━━━━━━━━━━━━━━━━\n\n🎵 **《鹿港小镇》**\n假如你先生来自鹿港小镇\n请问你是否看见我的爹娘\n我家就住在妈祖庙的后面\n卖着走向胜利的薯糖\n台北不是我的家\n我的家乡没有霓虹灯\n鹿港的街道 鹿港的渔村\n妈祖庙里烧香的人们\n台北不是我的家\n我的家乡没有霓虹灯\n鹿港的清晨 鹿港的黄昏\n徘徊在文明里的人们",
