    "quote": "如果我爱你，我也只会爱你一会儿。",
    "lyrics": "🎵 **《我们》**\n在寬闊的馬路邊狹窄的小巷\n我們窩居著仰望遠方的富麗堂皇\n陋室裡現實的哀傷\n被塗上幻想的蜜糖\n我們試著去相信美好未來的想像\n在和平的年代裡一片繁榮的景象\n我們創造並承擔發展帶來的影響\n肩上負擔著重量\n很難看清楚前方\n只能努力去修補殘缺的現狀\n我們一直在等待\n我們努力去堅強\n我們在忍耐中磨練內心的寬廣\n我們渴望被關愛\n我們呵護著希望\n我們相信這時代會被真誠改良\n在晃動的公車裡塞滿空蕩的心房\n我們始終在遵循人生的奔波匆忙\n創造太多繁華風光\n從來沒有機會欣賞\n我們還在寻找幸福的模樣\n在閃動的屏幕前激動而焦急的觀望\n我們無助卻渴望能給他人力量\n平凡不平庸的願望\n無聲卻格外的響亮\n我們一直在傳遞溫暖的火光\n我們一直等待\n我們努力去堅強\n我們在忍耐中磨練內心的寬廣\n我們渴望被關愛\n我們呵護著希望\n我們一直等待 我們努力去堅強\n我們在忍耐中磨練內心的寬廣\n我們渴望被關愛\n我們呵護著希望\n我們不斷在挫敗中微笑著起航",
