    "lyrics": "我有一个朋友，今年二十一岁\n一直喜欢穿白色的风衣住在盒子后面\n后面挂着照片，照片上的人在盒子里面\n每天早晨红色的尿布从阳具上升起\n升起让她看不出墓碑上的人的表情\n我的这个朋友，她说她是宝贝\n为何爸爸要丢她在这里\n他说他会回来，他说他在等待\n蓝色的海洋宁静而悠远\n她用过去的鲜血维持奄奄一息的生命\n等来的只是化妆后的猎狗在东张西望\n西边有座房子，春天传来掌声\n成人的无耻让她恶心\n东边有座房子，秋天传来笑声\n孩子的无知也让她恶心\n她在角落里伤心绝望被富裕的人遗忘\n她在流动的色彩里被岁月弄脏了衣裳\n我有一个朋友，有时我去看她\n永远看不出天空的颜色\n天空下的照片，像我用的纸片\n我又爱又恨又感到可怜\n轰轰烈烈尔虞我诈的世界生物团结\n一阵眩晕过后再看不见地上的鲜血\n世界在变我操蛋的理想还不能实现\n世界在变我操蛋的理想还不能实现\n世界在变我操蛋的理想还不能实现\n世界在变我操蛋的理想还不能实现\n理想在变这操蛋的世界还不能实现\n理想在变这操蛋的世界还不能实现",
