    "duration": 957,
    "quote": "在閃動的屏幕前激動而焦急的觀望，我們無助卻渴望能給他人力量。",
    "lyrics": "🎵 **《她》**\n她睁着朦胧的眼睛，带着疲惫慢慢地靠近\n她的微笑她的味道，从身体里发出暗淡的光\n她陷入怀疑的恐惧，对着镜子假装在哭泣\n她的疯狂她的迷茫，她说现在她还不太想，被他们慢慢地忘掉\n嘞嘞嘞……她要在阳光下，拼命地奔跑\n嘞嘞嘞……她要在空虚里，拼命地舞蹈\n她交替黑色的双腿，向着嘈杂虚无地喷发\n她的明亮她的晴朗，把无知化解成无聊的笑\n寂静从潮湿处涌来，在处女和荡妇间周转\n她的分裂她的错觉，她说不如从现在开始，像苹果一样地烂掉\n嘞嘞嘞……她要在阳光下，拼命地奔跑\n嘞嘞嘞……她要在恐惧里，拼命地舞蹈\n嘞嘞嘞……她要在阳光下，拼命地奔跑\n嘞嘞嘞……她要在迷惑里，拼命地舞蹈\n\n━━━━━━━━━━━━━━━━━━━━━\n\n🎵 **《我们》**\n在寬闊的馬路邊狹窄的小巷\n我們窩居著仰望遠方的富麗堂皇\n陋室裡現實的哀傷\n被塗上幻想的蜜糖\n我們試著去相信美好未來的想像\n在和平的年代裡一片繁榮的景象\n我們創造並承擔發展帶來的影響\n肩上負擔著重量\n很難看清楚前方\n只能努力去修補殘缺的現狀\n我們一直在等待\n我們努力去堅強\n我們在忍耐中磨練內心的寬廣\n我們渴望被關愛\n我們呵護著希望\n我們相信這時代會被真誠改良\n在晃動的公車裡塞滿空蕩的心房\n我們始終在遵循人生的奔波匆忙\n創造太多繁華風光\n從來沒有機會欣賞\n我們還在寻找幸福的模樣\n在閃動的屏幕前激動而焦急的觀望\n我們無助卻渴望能給他人力量\n平凡不平庸的願望\n無聲卻格外的響亮\n我們一直在傳遞溫暖的火光\n我們一直等待\n我們努力去堅強\n我們在忍耐中磨練內心的寬廣\n我們渴望被關愛\n我們呵護著希望\n我們一直等待 我們努力去堅強\n我們在忍耐中磨練內心的寬廣\n我們渴望被關愛\n我們呵護著希望\n我們不斷在挫敗中微笑著起航\n\n━━━━━━━━━━━━━━━━━━━━━\n\n🎵 **《年的春天》**\n姐姐，\n今夜我在等你\n那个夏天，那辆火车。\n带我们去一个地方\n爸爸，他在听着汽笛声\n妈妈，为你做了白裙子\n姐姐，\n今夜我在想你\n我的朋友，他们都老了。\n只有你，永远十七岁\n我已忘了家乡的春天是什么\n我已忘了你的颜色是什么\n我已忘了他们议论的是什么\n我已忘了明天的我是什么\n姐姐，\n今夜我在恨你\n你的眼睛出卖了我。\n你的爱毁灭了我\n什么时候我才能忘了你\n什么时候我才能靠近你\n什么时候我才能忘记你\n什么时候我才能靠近你",
