    "lyrics": "一天晚上我的一个朋友悄悄的来看我\n他的眼睛像外面的月亮是忧郁的\n他抓起我桌上的那个苹果轻轻的咬了一口\n从上衣的口袋里掏出一个信封对我说\n他说这世界是不是我们的\n我应该穿什么吃什么\n如果没有人看着我\n那该多快乐\n他说这世界不该是我们的\n爸爸妈妈也不该有的\n我可是个男人为什么打不起精神\n一些天像过去那样平淡的过去了\n在同样的一个夜晚那个朋友打来电话\n他说他在一个陌生的地方一个人唱着歌\n我看着他留下的那个信封想起他说的话\n他说这世界是不是我们的\n我应该穿什么吃什么\n如果没有人看着我\n那该多快乐\n他说这世界不该是我们的\n爸爸妈妈也不该有的\n我可是个男人为什么打不起精神",
