    "quote": "飞机飞过金色麦田，挡住人们的农田，有人在哭泣，有人在歌唱，有人生来有知己。",
    "lyrics": "这么多年你一个人一直在走\n方向和天气的节奏会让你忧愁\n你说你遇见了一大堆奇怪的人\n他们看上去好像都比你开心\n你能不能抽空替我去一个地方\n据说那的人都擅长给别人答案\n如果你想知道关于它的其他事情\n我也不会给你刘堃的电话号码\n多想和你一样臭不要脸\n墨镜和表情都挂在脸上\n穿什么吃什么玩什么都可以\n今天爱他明天恨他也可以\n这么多年我一个人一直在走\n走过了人性的背后和白云苍狗\n总以为答案会出现在下一个车站\n随后的事情我不说你也能明白\n悲伤是奢侈品我消受不起\n快乐像噩梦总让人惊醒\n你要哭吧就哭吧就随意吧\n反正我早已习惯不去相信\n悲伤是奢侈品我消受不起\n快乐像噩梦一转眼惊醒\n你要走吧就走吧就随意吧\n反正我早已决定不再回去",
