    "duration": 542,
    "quote": "家仇国恨的青年，写满字条的房间，这是谁的父亲在人间哭泣。",
    "lyrics": "🎵 **《杭州》**\n就像是一场战争\n现在需要大雨浇灭理性\n谁也无法逃脱\n或是减少伤亡\n黄楼里有个男人在弹钢琴\n身边的少女偷情\n一杯长岛下肚\n转身跳进西湖\n找也找不到九六年的痕迹\n忘也忘不了武林门的回忆\n为何在慌乱中冲进这城市把一切打乱\n是月亮 是清泉 是前年的犹豫\n错过是一个错误\n寻找是一个错误\n重塑是一个错误\n醒了才发现没有退路\n掏出你左手的手枪\n右手的菜刀\n中间的凶器\n壮烈的向我开炮\n灰飞烟灭的是我的灵魂\n藕断丝连的是这座城池\n家骏求求你\n在美丽的义乌等我\n为黑嫂 为桃花 为那盆炭火\n让我查一下谷歌地图北仑怎么走\n去看你 去爱你 再悄悄离去\n\n━━━━━━━━━━━━━━━━━━━━━\n\n🎵 **《我们》**\n在寬闊的馬路邊狹窄的小巷\n我們窩居著仰望遠方的富麗堂皇\n陋室裡現實的哀傷\n被塗上幻想的蜜糖\n我們試著去相信美好未來的想像\n在和平的年代裡一片繁榮的景象\n我們創造並承擔發展帶來的影響\n肩上負擔著重量\n很難看清楚前方\n只能努力去修補殘缺的現狀\n我們一直在等待\n我們努力去堅強\n我們在忍耐中磨練內心的寬廣\n我們渴望被關愛\n我們呵護著希望\n我們相信這時代會被真誠改良\n在晃動的公車裡塞滿空蕩的心房\n我們始終在遵循人生的奔波匆忙\n創造太多繁華風光\n從來沒有機會欣賞\n我們還在寻找幸福的模樣\n在閃動的屏幕前激動而焦急的觀望\n我們無助卻渴望能給他人力量\n平凡不平庸的願望\n無聲卻格外的響亮\n我們一直在傳遞溫暖的火光\n我們一直等待\n我們努力去堅強\n我們在忍耐中磨練內心的寬廣\n我們渴望被關愛\n我們呵護著希望\n我們一直等待 我們努力去堅強\n我們在忍耐中磨練內心的寬廣\n我們渴望被關愛\n我們呵護著希望\n我們不斷在挫敗中微笑著起航",
