    "id": 273,
    "title": "热河",
    "clean_title": "热河",
    "album": "李志 1701",
    "year": 2014,
    "duration": 406,
    "quote": "没有人在热河路谈恋爱，总有人在天黑时伤感。如果年轻时你没来过热河路，那你现在已经老了。",
    "lyrics": "热河路就像\n八十年代的金坛县\n梧桐垃圾灰尘\n和各式各样的杂货店\n人们总是早早的离开\n拉上卷帘门\n在天黑前穿上毛衣\n点一根烟\n热河路有一家\n开了好多年的理发店\n不管剪什么样的发型\n你只要付五块钱\n老板和她的妹妹坐在椅子上\n对着镜子一言不发\n他们的老家\n在身后在岸边在安徽全椒县\n没有人在热河路谈恋爱\n总有人在天亮时伤感\n如果年轻时你没来过热河路\n那你现在的生活是不是很幸福\n纪念碑旁\n有一家破旧的电影院\n往北走五百米\n就是南京火车西站\n每天都有外地人\n在直线和曲线之间迷路\n气喘嘘嘘眼泪模糊\n奔跑跌倒奔跑\n秋林龙虾换了新的地方\n32路还是穿过挹江门\n高架桥拆了修了新的隧道\n走来走去走不出我的盐仓桥\n来到城市已经八百九十六天\n热河路一直是相同的容颜\n偶尔有干净的潘西路过\n她不会说你好再见\n没有人在热河路谈恋爱\n总有人在天黑时伤感\n如果年轻时你来过热河路\n那你现在是不是已经被他们淹没\n没有新的衣服能让你爱恋\n总有一种天气让我怀念\n醒来或者吃饱又是一年\n相遇然后分别就在一天",
    "cover": "covers/cov_10601.jpg",
    "category": "studio",
    "city": null,
    "era": "era_10_15",
    "channel_url": "https://t.me/libimusic/1117",
    "msg_id": 1117
