    "lyrics": "隔壁的屋顶挡住了冬天的阳光\n你在阴影里琢磨着其余的明亮\n走过的行人都拥有相同的外套\n谁是谁的名字并不重要\n下水道里的伴侣用熟悉的声音\n说着今天马路上发生的事\n他们的头颅都抬得过高\n总以为明天会变得很好\n黄色的路灯是\n饥饿的时候\n让我们坐立不安\n美味的饼干\n黑色的马路是\n竞争对手的公司\n幸好他们睡的不太晚\n我不太擅长用深情的话\n描述此刻空空的冰冷饭桌\n我已经穿过所有能穿过的洞\n那些危险的东西不能带回来\n趁那些酒鬼还没有呕吐\n我要闭上眼打一个小盹\n饥肠辘辘让我感到羞愧\n想得太多也让我羞愧\n就算你\n用最好的水泥石灰\n瓷砖木头面膜肥皂\n保护你的卧室\n我也会\n拼尽力探索规划撕咬\n哪怕最后只是\n一颗小小米粒\n你休想\n杀尽我所有的兄弟姐妹\n母亲老子\n妻子孩子孙子\n因为我\n还可以输送无穷的液体\n给这个那个和那个和这个\n你这些人类",
