    "lyrics": "这是一个结婚的车队\n在无人的夜里奔跑\n我观望着找不到新郎在哪里\n灯光和星光 是祝福的烟火\n悲剧在天亮时发生\n毛毛你是个好姑娘 你要保护好你自己\n你可知世上没有什么好人 你别被他们都骗了\n毛毛你是个好姑娘 你要把持住你的欲望\n你可知我想像你一样纯洁 你不能比我还要放荡\n悲伤的事情 既然已经这样发生\n你就不能这样的看着我\n一切的一切不过只是野鸽子飞过天空\n孩子你最隐秘的幻想究竟是什么\n毛毛你个好姑娘 你要保护好你自己\n你可知世上没有什么好人 你别被他们都骗了\n毛毛你是个好姑娘 你要把持住你的欲望\n你可知我想像你一样纯洁 你不能比我还要放荡\n啦啦啦啦\n啦啦啦啦\n一切的一切不过只是野鸽子飞过天空\n孩子你最纯洁的幻想究竟是什么",
