    "quote": "他们说这世界上海最深，因为海里藏着无数人的眼泪。",
    "lyrics": "用那只缺角的身体\n去偷袭眼前\n这头午睡的大象\n再假装\n并没有发现\n厚实的皮肤\n能飞到树枝\n它们理解的白天就是\n此刻晃荡的海市蜃楼\n升腾的空气里\n没有绿草和刚刚学习飞翔的鸟\n啤酒不该是眼泪\n不该有颜色\n夜晚也不平整\n声音不该是美好\n谁又会介意\n只是表演缅怀怨念\n环卫工人不喝啤酒\n竹签无法继续勃起\n肮脏消失在火焰和唾液中\n破碎呐喊给天亮理由\n突突闪光的公共汽车\n催眠疲惫的福建老板\n孩子们在千里之外\n梦见一只瘸腿的大象",
