    "quote": "这是一只孤独的鸵鸟，在黑夜里拼命地奔跑。",
    "lyrics": "别把我和他们扯在一起\n我没有他们那么崇高，\n也没有他们那么装逼\n别管我，我只是一只发黑的苹果\n朋友，\n你的身材可别走样咯\n看着你成为一个胖子，\n多少我会有一点尴尬\n人群里不和谐的歌唱，\n我只是一头发情的鸵鸟\n是谁带你来看这场庙会\n行为掩饰后超越了思维\n舞台上的小丑和你的左小腿\n别管我，\n别把我和他们扯在一起\n让他们去寻找可能是高贵的荣耀\n我已经失去爱的本领\n也不会恨的那么聪明\n别管我，我只是发出下贱的声音\n世界被伤害了无法入睡\n声音被重复着怀疑眼泪\n中国是他们的也或是你们的\n别管我，\n我只是一个偶像派歌手\n是谁带你来看这场庙会\n行为掩饰后超越了思维\n舞台上的小丑和你的左小腿\n别管我，\n别把我和他们扯在一起\n世界被伤害了无法入睡\n声音被重复着怀疑眼泪\n是谁带你来看这场庙会\n行为掩饰后超越了思维",
