    "year": 2017,
    "duration": 378,
    "quote": "卑鄙是卑鄙者的通行证，高尚是高尚者的墓志铭。",
    "lyrics": "卑鄙是卑鄙者的通行证，\n高尚是高尚者的墓志铭。\n看吧，在那镀金的天空中，\n飘满了死者弯曲的倒影。\n冰川纪过去了，\n为什么到处都是冰凌？\n好望角发现了，\n为什么死海里千帆相竞？\n我来到这个世界上，\n只带来纸、绳索和身影，\n为了在审判之前，\n宣读那些被判决的声音。\n告诉你吧，世界\n我--不--相--信！\n纵使你脚下有一千名挑战者，\n那就把我算作第一千零一名。\n我不相信天是蓝的，\n我不相信雷的电光；\n我不相信梦是假的，\n我不相信死无报应。\n如果海洋注定要翻溃，\n就让所有的苦水都注入我心中，\n如果陆地注定要上升，\n就让人类重新选择生存的峰顶。\n沉沦的群星在闪烁，\n没有遮蔽的银河，\n也许是几千年之后，\n未来人们凝视的眼睛。",
