    "lyrics": "什么时候要忘记你，什么时候就想念你\n什么时候握住**抚摸胸口\n什么时候遇见你，什么时候失去你\n我就像喝多了酒，十八岁的忧愁\n你还在笼罩我，你的名字还在纠结我\n我只是一个人，我的歌里全都是你\n点燃这根香烟吧，点燃这个夜晚吧\n我无所谓，开心或是伤悲\n屋顶晴朗的早晨，触手可及的距离\n他们告诉我，梦也是秘密\n你还在改变我，你的歌声还在温暖我\n我只能一个人，我的明天早就给了你\n谁能够停止我，谁的声音能够拯救我\n谁试图靠近你，谁的声音已经改变你\n喝完你留下的酒，喝完你给的命运\n我抬起头，秋天已经来临",
