    "lyrics": "我在恶心的世界里，寻找一个像你的人\n在每个想你的夏天里，等另一种感情\n我在失败的生活里，寻找一个爱我的人\n我的悲伤，浪漫和幻想，不对她说起\n我再也不会把自己，愚蠢的交给过去\n我的生活和我的想法，从此相隔了万里\n我整夜整夜地失眠，不是为了和谁再相见\n曾经爱你的每一条街，\n是我新鲜生活的起点\n我在陌生的感动里，寻找一个像你的人\n就算像过去一样被误解，不快乐又如何\n我在干裂的春天里，寻找一个平凡的人\n她的善良，甜蜜和阳光，陪伴我自己\n我再也不会把自己，彻底的交给一个人\n我的理想就像这黑夜，一分一秒的断裂\n我一天一天地发呆，不是为了酝酿些什么\n真情早已经被他们毁灭，\n还有什么不能去拒绝\n是否你也在沉默里，寻找一个像我的人\n在每个想我的季节里，和他们在一起",
