    "duration": 0,
    "quote": "港岛妹妹，你献给我的西班牙馅饼，甜蜜的融化了我，茫茫的胆量。",
    "lyrics": "飞机飞过天空，天空之城\n落雨下的黄昏的我们\n此刻我在异乡的夜里\n感觉着你忽明忽暗\n我想回到过去，沉默着欢喜\n天空之城在哭泣，越来越明亮的你\n爱情不过是生活的屁\n折磨着我也折磨着你\n港岛妹妹，你献给我的西班牙馅饼\n甜蜜地融化了我，天空之城在哭泣\n港岛妹妹，我们曾拥有的甜蜜的爱情\n疯狂地撕裂了我，天空之城在哭泣\n港岛妹妹，你献给我的西班牙馅饼\n甜蜜地融化了我，天空之城在哭泣\n港岛妹妹，我们曾拥有的甜蜜的爱情\n疯狂地撕裂了我，天空之城在哭泣\n港岛妹妹，你献给我的西班牙馅饼\n甜蜜地融化了我，天空之城在哭泣\n港岛妹妹，我们曾拥有的甜蜜的爱情\n疯狂地撕裂了我，天空之城在哭泣\n有人路过那里，回来告诉我\n天空之城在哭泣，无法呼吸的你\n此刻我在异乡的夜里\n想念着你越来越远",
