    "lyrics": "多多你不要哭\n长大你就会清楚\n这世界没有人\n对你真的在乎\n多多你不要怕\n我不会逼你学吉他\n你是你我是我\n各有各的想法\n不久以后的某天\n我就这样的老了\n你不用装作多么的难过\n你是你我是我\n谁都难免会孤独\n你是你我是我\n谁都难免会寂寞\n多多你别问我\n生活到底是什么\n他们人类没道理\n我不懂的太多\n多多你别害怕\n如果你真的爱上他\n用真心用真情\n别管以后的结果\n必然有那么一天\n你就突然离开我\n你不要装作多么的眷恋\n你走吧你笑吧\n你找寻你自己吧\n你走吧你笑吧\n你找寻你自己吧\n也许不久的某天\n我突然就离开你\n你不要装作多么的眷恋\n你走吧你笑吧\n你找寻你自己吧\n你走吧你笑吧\n你找寻你自己吧\n你走吧你笑吧\n你找寻你自己吧\n你走吧你笑吧\n你找寻你自己吧",
