    "duration": 758,
    "quote": "家仇国恨的青年，写满字条的房间，这是谁的父亲在人间哭泣。",
    "lyrics": "🎵 **《不多》**\n多多你不要哭\n长大你就会清楚\n这世界没有人\n对你真的在乎\n多多你不要怕\n我不会逼你学吉他\n你是你我是我\n各有各的想法\n不久以后的某天\n我就这样的老了\n你不用装作多么的难过\n你是你我是我\n谁都难免会孤独\n你是你我是我\n谁都难免会寂寞\n多多你别问我\n生活到底是什么\n他们人类没道理\n我不懂的太多\n多多你别害怕\n如果你真的爱上他\n用真心用真情\n别管以后的结果\n必然有那么一天\n你就突然离开我\n你不要装作多么的眷恋\n你走吧你笑吧\n你找寻你自己吧\n你走吧你笑吧\n你找寻你自己吧\n也许不久的某天\n我突然就离开你\n你不要装作多么的眷恋\n你走吧你笑吧\n你找寻你自己吧\n你走吧你笑吧\n你找寻你自己吧\n你走吧你笑吧\n你找寻你自己吧\n你走吧你笑吧\n你找寻你自己吧\n\n━━━━━━━━━━━━━━━━━━━━━\n\n🎵 **《杭州》**\n就像是一场战争\n现在需要大雨浇灭理性\n谁也无法逃脱\n或是减少伤亡\n黄楼里有个男人在弹钢琴\n身边的少女偷情\n一杯长岛下肚\n转身跳进西湖\n找也找不到九六年的痕迹\n忘也忘不了武林门的回忆\n为何在慌乱中冲进这城市把一切打乱\n是月亮 是清泉 是前年的犹豫\n错过是一个错误\n寻找是一个错误\n重塑是一个错误\n醒了才发现没有退路\n掏出你左手的手枪\n右手的菜刀\n中间的凶器\n壮烈的向我开炮\n灰飞烟灭的是我的灵魂\n藕断丝连的是这座城池\n家骏求求你\n在美丽的义乌等我\n为黑嫂 为桃花 为那盆炭火\n让我查一下谷歌地图北仑怎么走\n去看你 去爱你 再悄悄离去",
