    "album": "洗心革面 跨年音乐会",
    "year": 2019,
    "duration": 902,
    "quote": "关于郑州我想的全是你，想来生活无非是痛苦和美丽。",
    "lyrics": "🎵 **《关于郑州的记忆》**\n关于郑州我知道的不多\n为了爱情曾经去过那里\n多少次在火车上路过这城市\n一个人悄悄地想起她\n她说她喜欢郑州冬天的阳光\n巷子里飘满煤炉的味道\n雾气穿过她年轻的脖子\n直到今天都没有散去\n关于郑州我想的全是你\n想来想去都是忏悔和委屈\n关于郑州我爱的全是你\n爱来爱去不明白爱的意义\n关于郑州只是偶尔想起\n现在她的味道都在回忆里\n每次和朋友说起过去的旅行\n我不敢说我曾去过那里\n关于郑州我想的全是你\n想来生活无非是痛苦和美丽\n关于郑州我爱的全是你\n爱到最后我们都无路可去\n似是而非或是世事可畏\n有情有义又是有米无炊\n时间改变了很多也什么都没有\n让我再次拥抱你 郑州\n\n━━━━━━━━━━━━━━━━━━━━━\n\n🎵 **《春末的南方城市》**\n这个下雨的清晨\n我从南方的这个城市准备去南方的那个城市\n我和我的兄弟在一家包子铺门口分手赶往远处的站台\n车上的白领睡意朦胧隔着眼屎看着我\n这让人心慌 这让人心慌\n这让人心慌 这让人心慌\n这个下雨的清晨\n我从城市的这头渡过河去城市的那头\n街上的红灯绿灯闪烁不停闪烁不停闪烁\n这让人心慌\n兄弟在玻璃的建筑里 我在潮湿的路上\n人们重复着重复着重复着重复着重复\n这让人心慌 这让人心慌\n这让人心慌 这让人心慌\n这让人心慌\n不知道有谁能让你诉说\n你这样的生活到底为了什么\n我看见你靠在窗口沉默\n路过了青春我们还拥有什么\n这让人心慌 这让人心慌\n这让人心慌 这让人心慌\n不知道有谁能让你诉说\n你这样的生活到底为了什么\n我看见你靠在窗口沉默\n路过了青春我们还拥有什么\n这让人心慌 这让人心慌\n这让人心慌 这让人心慌\n这让人心慌 这让人心慌\n这让人心慌 这让人心慌\n这让人心慌 这让人心慌",
