    "lyrics": "就像是一场战争\n现在需要大雨浇灭理性\n谁也无法逃脱\n或是减少伤亡\n黄楼里有个男人在弹钢琴\n身边的少女偷情\n一杯长岛下肚\n转身跳进西湖\n找也找不到九六年的痕迹\n忘也忘不了武林门的回忆\n为何在慌乱中冲进这城市把一切打乱\n是月亮 是清泉 是前年的犹豫\n错过是一个错误\n寻找是一个错误\n重塑是一个错误\n醒了才发现没有退路\n掏出你左手的手枪\n右手的菜刀\n中间的凶器\n壮烈的向我开炮\n灰飞烟灭的是我的灵魂\n藕断丝连的是这座城池\n家骏求求你\n在美丽的义乌等我\n为黑嫂 为桃花 为那盆炭火\n让我查一下谷歌地图北仑怎么走\n去看你 去爱你 再悄悄离去",
