    "lyrics": "🎵 **《鸵鸟》**\n别把我和他们扯在一起\n我没有他们那么崇高，\n也没有他们那么装逼\n别管我，我只是一只发黑的苹果\n朋友，\n你的身材可别走样咯\n看着你成为一个胖子，\n多少我会有一点尴尬\n人群里不和谐的歌唱，\n我只是一头发情的鸵鸟\n是谁带你来看这场庙会\n行为掩饰后超越了思维\n舞台上的小丑和你的左小腿\n别管我，\n别把我和他们扯在一起\n让他们去寻找可能是高贵的荣耀\n我已经失去爱的本领\n也不会恨的那么聪明\n别管我，我只是发出下贱的声音\n世界被伤害了无法入睡\n声音被重复着怀疑眼泪\n中国是他们的也或是你们的\n别管我，\n我只是一个偶像派歌手\n是谁带你来看这场庙会\n行为掩饰后超越了思维\n舞台上的小丑和你的左小腿\n别管我，\n别把我和他们扯在一起\n世界被伤害了无法入睡\n声音被重复着怀疑眼泪\n是谁带你来看这场庙会\n行为掩饰后超越了思维\n\n━━━━━━━━━━━━━━━━━━━━━\n\n🎵 **《墙上的向日葵》**\n窗外的风，吹过我的房间\n吹动，你的向日葵\n城市就躲在光明的背后\n光明只是你隐秘的哀愁\n时光就这样悄悄地溜走\n溜走\n十年的风景就像下午的云\n你和你的头发摇曳不定\n带着她的影子站在街头\n像恐惧的鱼拼命地游\n时光就这样悄悄地溜走\n什么是我们分开的借口\n什么能让我为谁停留\n时光又一次忧伤地溜走\n溜走\n\n━━━━━━━━━━━━━━━━━━━━━\n\n🎵 **《这个世界会好吗》**\n妈妈，他们抛弃了我\n像歌唱一样抛弃了我\n妈妈，我是多么爱你\n当你沉默的时候我爱你\n只是那些猛烈的情绪\n在睡不着的时候折磨着我\n我的早已死去的父亲\n在没有星星的夜晚看着你\n妈妈，我会在夏天开放吗\n像你曾经的容颜那样\n妈妈，这种失落会持久吗\n这个世界会好吗\n忘记一些隐秘的委屈\n在回头观望的时候迷失了自己\n我的正在老去的身体\n从某一点开始就在渐渐逝去\n妈妈我爱你\n妈妈，我居然爱上了她\n像歌唱一样就爱上了她\n妈妈，当你又回首一切\n这个世界会好吗\n我是多么恨你\n当我歌唱的时候 我恨你\n\n━━━━━━━━━━━━━━━━━━━━━\n\n🎵 **《定西》**\n这么多年你一个人一直在走\n方向和天气的节奏会让你忧愁\n你说你遇见了一大堆奇怪的人\n他们看上去好像都比你开心\n你能不能抽空替我去一个地方\n据说那的人都擅长给别人答案\n如果你想知道关于它的其他事情\n我也不会给你刘堃的电话号码\n多想和你一样臭不要脸\n墨镜和表情都挂在脸上\n穿什么吃什么玩什么都可以\n今天爱他明天恨他也可以\n这么多年我一个人一直在走\n走过了人性的背后和白云苍狗\n总以为答案会出现在下一个车站\n随后的事情我不说你也能明白\n悲伤是奢侈品我消受不起\n快乐像噩梦总让人惊醒\n你要哭吧就哭吧就随意吧\n反正我早已习惯不去相信\n悲伤是奢侈品我消受不起\n快乐像噩梦一转眼惊醒\n你要走吧就走吧就随意吧\n反正我早已决定不再回去",
