    "duration": 242,
    "quote": "这个世界会好吗，忘记一些隐秘的委屈。",
    "lyrics": "妈妈，他们抛弃了我\n像歌唱一样抛弃了我\n妈妈，我是多么爱你\n当你沉默的时候我爱你\n只是那些猛烈的情绪\n在睡不着的时候折磨着我\n我的早已死去的父亲\n在没有星星的夜晚看着你\n妈妈，我会在夏天开放吗\n像你曾经的容颜那样\n妈妈，这种失落会持久吗\n这个世界会好吗\n忘记一些隐秘的委屈\n在回头观望的时候迷失了自己\n我的正在老去的身体\n从某一点开始就在渐渐逝去\n妈妈我爱你\n妈妈，我居然爱上了她\n像歌唱一样就爱上了她\n妈妈，当你又回首一切\n这个世界会好吗\n我是多么恨你\n当我歌唱的时候 我恨你",
