    "title": "关于郑州的记忆 (相信未来版)Memory about Zhengzhou",
    "clean_title": "关于郑州的记忆 Memory about Zhengzhou",
    "album": "Best Selection Songs 2004-2018 (Vol.2)",
    "year": 2020,
    "duration": 363,
    "quote": "关于郑州我想的全是你，想来生活无非是痛苦和美丽。",
    "lyrics": "🎵 **《关于郑州的记忆》**\n关于郑州我知道的不多\n为了爱情曾经去过那里\n多少次在火车上路过这城市\n一个人悄悄地想起她\n她说她喜欢郑州冬天的阳光\n巷子里飘满煤炉的味道\n雾气穿过她年轻的脖子\n直到今天都没有散去\n关于郑州我想的全是你\n想来想去都是忏悔和委屈\n关于郑州我爱的全是你\n爱来爱去不明白爱的意义\n关于郑州只是偶尔想起\n现在她的味道都在回忆里\n每次和朋友说起过去的旅行\n我不敢说我曾去过那里\n关于郑州我想的全是你\n想来生活无非是痛苦和美丽\n关于郑州我爱的全是你\n爱到最后我们都无路可去\n似是而非或是世事可畏\n有情有义又是有米无炊\n时间改变了很多也什么都没有\n让我再次拥抱你 郑州",
    "cover": "covers/cov_60816.jpg",
    "category": "japan",
    "city": "郑州",
    "era": "era_19_25",
