    "id": 370,
    "title": "山陰路の夏(2011)(山阴路的夏天Nanjing summer day)",
    "clean_title": "山陰路之夏",
    "album": "Best Selection Songs 2004-2018 (Vol.2)",
    "year": 2020,
    "duration": 280,
    "quote": "就像你沉默的委屈，一转眼，我们的城市又到了夏天，。",
    "lyrics": "🎵 **《山阴路的夏天》**\n这次你离开了没有像以前那样说再见，\n再见也他妈的只是再见\n我们之间从来没有想象的那么接近，\n只是两棵树的距离\n你是否还记得山阴路我八楼的房间，\n房间里唱歌的日日夜夜\n那么热的夏天你看着外面，\n看着你在消逝的容颜\n我多么想念你走在我身边的样子，\n想起来我的爱就不能停止\n南京的雨不停地下不停地下，\n就像你沉默的委屈\n一转眼，我们的城市又到了夏天，\n对面走来的人都眯着眼\n人们不敢说话不敢停下脚步，\n因为心动常常带来危险\n我多么想念你走在我身边的样子，\n想起来我的爱就不能停止\n南京的雨不停地下不停地下，\n有些人却注定要相遇\n你是一片光荣的叶子落在我卑贱的心\n像往常一样我为自己生气并且歌唱\n那么乏力，爱也吹不动的叶子",
