    "duration": 275,
    "quote": "莫名其妙的情绪从山顶上飘过来，飞也飞不出的包围对我说：。",
    "lyrics": "路的尽头是湖\n湖的尽头是你\n你的尽头有一个人看着我，\n说：明天，一起下葬\n生的尽头是爱\n爱的尽头是船\n船的尽头有一片云围绕我，\n说：来吧，一起下葬\n莫名其妙的情绪从山顶上飘过来\n飞也飞不出的包围对我说：\n一起下葬……\n莫名其妙的情绪从山顶上飘过来\n飞也飞不出的包围对我说：\n死亡和我的梦想曾经如此的接近\n三十三年的挣脱脱不了，\n如何是好……",
    "cover": "covers/cov_78765.jpg",
