    "lyrics": "欧米嘎，\n你可看见昨天黄昏屋顶的云\n它多么像你，\n游移不定\n青春啊，\n让我忘记这故事那身体和昨天的梦\n循环的你，\n问我幸福在哪里\n阳光下的你坐上一辆蓝色汽车\n抚摸着背包里的玩具陪他哭泣\n无处可逃，一片空白\n梧桐下的人们，忽明忽暗\n欧米嘎，\n我不是在每个勃起的清晨才想起你\n你的样子，\n他们早就忘了\n撕裂吧，\n如果我没来过这疯狂的荒谬的世界\n南京已老了，\n我就快死了\n时常会去假设另一种生活\n把一切安排的不像现在遥远\n我不该如此伤心啊\n孩子们会跳舞，\n死神也歌唱\n从一个城市谨慎着来看我\n透过床头的玻璃看着外面\n无处可逃，你沉默了\n四月的早晨，让人悲伤\n青春啊，\n总是在这样分裂的失落的煎熬的夜晚让人伤心\n我多么想你，\n只能轻轻唱歌",
