    "lyrics": "🎵 **《鸵鸟》**\n别把我和他们扯在一起\n我没有他们那么崇高，\n也没有他们那么装逼\n别管我，我只是一只发黑的苹果\n朋友，\n你的身材可别走样咯\n看着你成为一个胖子，\n多少我会有一点尴尬\n人群里不和谐的歌唱，\n我只是一头发情的鸵鸟\n是谁带你来看这场庙会\n行为掩饰后超越了思维\n舞台上的小丑和你的左小腿\n别管我，\n别把我和他们扯在一起\n让他们去寻找可能是高贵的荣耀\n我已经失去爱的本领\n也不会恨的那么聪明\n别管我，我只是发出下贱的声音\n世界被伤害了无法入睡\n声音被重复着怀疑眼泪\n中国是他们的也或是你们的\n别管我，\n我只是一个偶像派歌手\n是谁带你来看这场庙会\n行为掩饰后超越了思维\n舞台上的小丑和你的左小腿\n别管我，\n别把我和他们扯在一起\n世界被伤害了无法入睡\n声音被重复着怀疑眼泪\n是谁带你来看这场庙会\n行为掩饰后超越了思维\n\n━━━━━━━━━━━━━━━━━━━━━\n\n🎵 **《墙上的向日葵》**\n窗外的风，吹过我的房间\n吹动，你的向日葵\n城市就躲在光明的背后\n光明只是你隐秘的哀愁\n时光就这样悄悄地溜走\n溜走\n十年的风景就像下午的云\n你和你的头发摇曳不定\n带着她的影子站在街头\n像恐惧的鱼拼命地游\n时光就这样悄悄地溜走\n什么是我们分开的借口\n什么能让我为谁停留\n时光又一次忧伤地溜走\n溜走\n\n━━━━━━━━━━━━━━━━━━━━━\n\n🎵 **《鼠说》**\n隔壁的屋顶挡住了冬天的阳光\n你在阴影里琢磨着其余的明亮\n走过的行人都拥有相同的外套\n谁是谁的名字并不重要\n下水道里的伴侣用熟悉的声音\n说着今天马路上发生的事\n他们的头颅都抬得过高\n总以为明天会变得很好\n黄色的路灯是\n饥饿的时候\n让我们坐立不安\n美味的饼干\n黑色的马路是\n竞争对手的公司\n幸好他们睡的不太晚\n我不太擅长用深情的话\n描述此刻空空的冰冷饭桌\n我已经穿过所有能穿过的洞\n那些危险的东西不能带回来\n趁那些酒鬼还没有呕吐\n我要闭上眼打一个小盹\n饥肠辘辘让我感到羞愧\n想得太多也让我羞愧\n就算你\n用最好的水泥石灰\n瓷砖木头面膜肥皂\n保护你的卧室\n我也会\n拼尽力探索规划撕咬\n哪怕最后只是\n一颗小小米粒\n你休想\n杀尽我所有的兄弟姐妹\n母亲老子\n妻子孩子孙子\n因为我\n还可以输送无穷的液体\n给这个那个和那个和这个\n你这些人类",
