    "quote": "没有人在热河路谈恋爱，总有人在天黑时伤感。如果年轻时你没来过热河路，那你现在已经老了。",
    "lyrics": "🎵 **《大象》**\n用那只缺角的身体\n去偷袭眼前\n这头午睡的大象\n再假装\n并没有发现\n厚实的皮肤\n能飞到树枝\n它们理解的白天就是\n此刻晃荡的海市蜃楼\n升腾的空气里\n没有绿草和刚刚学习飞翔的鸟\n啤酒不该是眼泪\n不该有颜色\n夜晚也不平整\n声音不该是美好\n谁又会介意\n只是表演缅怀怨念\n环卫工人不喝啤酒\n竹签无法继续勃起\n肮脏消失在火焰和唾液中\n破碎呐喊给天亮理由\n突突闪光的公共汽车\n催眠疲惫的福建老板\n孩子们在千里之外\n梦见一只瘸腿的大象\n\n━━━━━━━━━━━━━━━━━━━━━\n\n🎵 **《门》**\n总在这种时候，感觉自己已经飞的太远\n路灯全都灭了，不能破坏别人的幸福\n从没见过的细胞，睡衣和行星\n还有趴在玻璃上的灵魂\n它让我的心凉了又热了\n它说生生死死的爱恋又能如何\n相信吧，相信我们曾经恐惧的一切\n相信吧，门开了\n相信吧，相信我们曾经无奈的岁月\n门开了，它来了\n有时欣喜若狂，有时感觉不到生长\n黑暗里的秘密，你天生的美丽\n孤独来自脆弱的敏感\n敏感无法把美丽看穿\n相信吧，相信轰轰烈烈是你的未来\n相信吧，门开了\n相信吧，相信反反复复是我们情怀\n门开了，它来了\n\n━━━━━━━━━━━━━━━━━━━━━\n\n🎵 **《来了》**\n爱情来了\n她穿过夜色来看望一个人\n那不是我 是我的兄弟\n她背对着我脱下淋湿的衣服\n我看见外面两只喜鹊在打架\n我系进着鞋带冲进这夜色 夜色在唱 在唱\n来来来 ...\n理想来了\n它是个被母亲遗弃的小孩\n有一双结实的大腿蹦蹦跳跳到处乱跑\n我的兄弟曾经那么疯狂的爱着它 跟随着它\n不知道什么时候兄弟偷偷哭泣 要放弃它 于是唱\n来来来 ...\n命运来了\n它带着天平给每个人算命\n我看着它 睡着了\n我曾经那么无知的鄙视它 诅咒它\n如今我跪倒着苛求个机会 它看着我笑了 于是我唱\n来来 ...\n不管曾经或是以后\n拥有是什么\n请你相信我 我还会唱歌\n或许生死 或许悲观 离别是什么\n亲爱的兄弟 我还会唱歌\n不管永远 或是现在 会有些什么\n请你相信我 我还会唱歌\n来来来 ....\n\n━━━━━━━━━━━━━━━━━━━━━\n\n🎵 **《热河》**\n热河路就像\n八十年代的金坛县\n梧桐垃圾灰尘\n和各式各样的杂货店\n人们总是早早的离开\n拉上卷帘门\n在天黑前穿上毛衣\n点一根烟\n热河路有一家\n开了好多年的理发店\n不管剪什么样的发型\n你只要付五块钱\n老板和她的妹妹坐在椅子上\n对着镜子一言不发\n他们的老家\n在身后在岸边在安徽全椒县\n没有人在热河路谈恋爱\n总有人在天亮时伤感\n如果年轻时你没来过热河路\n那你现在的生活是不是很幸福\n纪念碑旁\n有一家破旧的电影院\n往北走五百米\n就是南京火车西站\n每天都有外地人\n在直线和曲线之间迷路\n气喘嘘嘘眼泪模糊\n奔跑跌倒奔跑\n秋林龙虾换了新的地方\n32路还是穿过挹江门\n高架桥拆了修了新的隧道\n走来走去走不出我的盐仓桥\n来到城市已经八百九十六天\n热河路一直是相同的容颜\n偶尔有干净的潘西路过\n她不会说你好再见\n没有人在热河路谈恋爱\n总有人在天黑时伤感\n如果年轻时你来过热河路\n那你现在是不是已经被他们淹没\n没有新的衣服能让你爱恋\n总有一种天气让我怀念\n醒来或者吃饱又是一年\n相遇然后分别就在一天",
