    "quote": "我我需要需要感谢我，太和音乐集团的老大。",
    "lyrics": "我要感谢一些人\n2025叁缺壹吉隆坡站\n这个场地是我从业以来\n演过我最喜欢的一个场地\n比我们南京那个场地还要好\n所以\n所以我要特别特别感谢这边的老板\n周家海大哥\n自从我们对接上之后\n他一直在帮我处理很多事情\n所以我才有精力把我的时间放在演出上面\n然后还要特别感谢杨浩宇\n因为是他介绍我跟周家海大哥认识\n本来浩宇也要来\n但是他没来\n我也不知道\n他也是\n然后要感谢t总\n我没见过他\n是我一个大哥拉了一个群\nt总在在本地反正什么都搞得定\n然后前前两天\n前两天演出前\n大概就三天三天四天\n然后t总在群里面问我说\n你要不要做个广告什么之类的\n所以所以后来就做了那个\n然后本来是演出开始前那个就下了\n但t总说既然大家这么喜欢\n就再放一天吧\n好像呃\n因为这两天我也在休息呃\n我我需要需要感谢我\n太和音乐集团的老大\n在这6年里面\n他跟我没有提任何要求\n就是陪着我\n然后我需要的时候他就出现\n我嫌他烦的时候\n那我走吧\n所以这是跟这场演出相关的这几个人\n我要特别感谢\n当然生意里面有很多人需要感谢我\n我这么多年\n就是靠很多很多人在帮助我\n我才走到现在\n然后给我勇气\n当然包括你们\n虽然虽然我老是\n老是说你们这个那个那个这个\n但是但是我心里是心里是知道的\n而且而且\n而且我觉得你们大部分人是\n能够感受到我对你们的善意\n只不过我在上面点到的就是\n就那个腻腻歪歪的那个对吧\n那个是那个是\n那个是什么\n叫什么男团女团玩的玩意不要\n我就觉得\n我就觉得\n我尽力的做个演出\n就是就是\n对你们最大的善意\n我不会其它的",
