    "quote": "如今所有的梦都已成真，如今所有的伤都已抚平，今天我要做一顿丰盛的晚餐。",
    "lyrics": "被禁忌的游戏+来了+忽然\n2025叁缺壹吉隆坡站\n沉默的你 阳光萧瑟的树林\n那些你爱的人 温柔的那么柔软\n无知的我 是落叶落魄又落魄\n曾经幻灭的岁月 穿插沉默的现在\n呼啸而过的青春 沉默不语的你\n即使给我个灿烂明天 让我忏悔的你\n这被禁忌的游戏 早已忘记的岁月\n这被禁忌的游戏 一如既往的岁月\n随风飘荡的我们 黑夜里寻找一点点欢愉\n再次面对这春色 失落的不知所以\n暗自叹息又暗自伤心 游戏已如此陌生\n看往川流的人群 穿越沉默的现在\n呼啸而过的青春 沉默不语的你\n即使给我个灿烂明天 让我忏悔的你\n这被禁忌的游戏 早已忘记了岁月\n这被禁忌的游戏 一如既往的岁月\n啦\n爱情来了\n她穿过夜色来看望一个人\n那不是我 是我的兄弟\n她背对着我脱下淋湿的衣服\n我看见外面两只喜鹊在打架\n我系进着鞋带冲进这夜色 夜色在唱 在唱\n理想来了\n它是个被母亲遗弃的小孩\n有一双结实的大腿蹦蹦跳跳到处乱跑\n我的兄弟曾经那么疯狂的爱着它 跟随着它\n不知道什么时候兄弟偷偷哭泣 要放弃它 于是唱\n命运来了\n它带着天平给每个人算命\n我看着它 笑了 睡着了\n如今我跪倒着苛求个机会 它看着我笑了 睡着了\n他就睡着\n他们 睡着了\n来来来......\n忽然就流出泪来\n忽然想要听到她的声音\n而我却什么话都说不出来\n是谁在温暖你\n有谁会让我觉得这夜晚还有期盼\n我就会跟着它去远行\n可是你在哪里\n可是明天醒来的第一脸阳光\n是否，会像梦里一样明亮\n幻想朝西的生活\n幻想着你被害怕定格的角落\n最后，我一个人越走越孤单\n幻想朝西的生活\n幻想着你被灯光伤感了寂寞\n最后，你一个人越走越孤单\n害怕朝西的生活\n害怕着你被灯光伤感了寂寞\n最后，我们就越走越孤单",
