    "lyrics": "山阴路的夏天\n专辑发布：2025.6.13\n专辑介绍：叁缺壹日本巡演 东京站现场录音 2024/5/2\n请支持正版，正版购买地址\nhttps://tower.jp/item/6849478\n这次你离开了没有像以前\n那样说再见\n再见也他妈的只是再见\n我们之间从来没有想象的那么接近\n只是两棵树的距离\n你是否还记得山阴路我八楼的房间\n房间里唱歌的日日夜夜\n那么热的夏天你看着外面\n看着你在消逝的容颜\n我多么想念你走在我身边的样子\n想起来我的爱就不能停止\n南京的雨不停地下不停地下\n就像你沉默的委屈\n一转眼我们的城市又到了夏天\n对面走来的人都眯着眼\n人们不敢说话不敢停下脚步\n因为心动常常带来危险\n我多么想念你走在我身边的样子\n想起来我的爱就不能停止\n南京的雨不停地下不停地下\n有些人却注定要相遇\n你是一片光荣的叶子\n落在我卑贱的心\n像往常一样我为自己生气并且歌唱\n那么乏力 爱也吹不动的叶子\n小黑吟唱",
