    "duration": 821,
    "quote": "我还得挑战，我得挑战我自己。",
    "lyrics": "结尾-团队介绍\n2025叁缺壹吉隆坡站\n我们的鼓手武勇恒\n他是丰台区舞王\n我第一次知道贝爷是20年前\n我在首都体育馆看老师的演演出\n然后当时贝爷打的鼓\n听这个动静有点东西\n所以我就想能不能有可以一起合作\n但没想到需要20年时间\n我们才能一起\n吉他手冯冲\n冯冲的外号是北京市朝阳区小slash\n所以你别看他长得五大三粗的\n但是他特别细腻\n是一个好人\n平时不抽烟不喝酒\n也不泡妞\n也不打游戏\n也不炒股\n哈哈哈特别好\n我我第一次跟他\n跟他面对面是爽子的演出\n爽子有一年演出我亲自去看\n然后看完呢\n一激动亲自上台给他返了个场\n我在台上弹了吉他\n唱了个歌\n然后冲哥就在旁边没动\n我整首歌唱完了\n他都没有找到我什么调\n那个就四个和弦\n他都不知道\n呃冯冲\n胡晨\n他是我们乐队年纪最小\n呃对\n今年31是吧\n比我大了6岁\n8岁\n整个我们这次的工作\n排练演出\n其实整个乐队里面\n我最感动的就是胡晨\n他非常非常非常的认真\n因为他兼顾了电吉他\n木吉他民谣吉他\n然后大量的歌曲\n他以前不知道我是谁\n因为他总是给那些流量歌手做演出\n哈哈哈\n但是但是他拿到我东西之后\n我们的音频发给他\n他每天都在跟周亮在研究每一个小节\n每一个音色\n甚至这个拨片多少厚度\n天天在琢磨\n我们所有的工作群里面\n他永远是第一个回信息\n我发的每一句话\n哪怕是吹牛逼\n他也会回\n能够多一点像\n胡晨这样的年轻的职业的音乐人\n那我们的音乐绝对不会这么差\n我们的队长李九君\n是江苏南京人\n呃\n那个初中辍学\n就去当兵了\n然后呢\n当兵体能又不好\n所以当了个文艺兵\n那文艺兵班长就说你会什么乐器\n然后就就敲了个三角体\nxiu\n后来就发发愤图强\n开始弹Bass\n呃九君也是一个特别典型的音乐人\n他的从艺30年\n从摇滚乐到流行乐到综艺\n全部干了一圈\n他最早是跟？弹Bass\n包括你们看过的中国好声音\n所有的歌都他弹的\n但是你们不知道他是谁对不对\n所以朋友们千万不要弹贝斯\n换一个乐器\n那九君有有两个世界名曲\n他录过两个世界名曲\n一个叫关于郑州的记忆\n当时是他那个贝斯他录的\n还有还有一个你们都知道\n蓝莲花\n蓝莲花还是比那个郑州要火一点吧\n口琴陈岍 他就不用多说了吧\n我看见他都烦\n键盘黄毅\n黄毅是那个\n第16届肖邦钢琴大赛第八名\n当时一共7个人参加\n大家都弹得不好\n说我去吧\n我跟黄毅在\n从一起工作到现在\n我特别感动\n你知道为什么吗\n当他发现我是个认真的人之后\n他就一直对我笑\n所以我们都喜欢跟认真的人一起工作\n所以黄毅也是\n他旁边\n文智涌\n可能是中国最有名的小号手\n因为他总是跟一些大腕合作\n所以他就蹭流量蹭到蹭到现在\n我跟文师傅是十几年前就就合作过\n他们帮我帮我录音\n但演出一直没有演过\n他主要是在爵士那一块\n就天天那个有的没的\n那我和弦\n和弦我就会四个\n我怎么跟他玩嘛\n但我们是特别好的朋友\n本来呢这个文智涌吹的\n他排练第一天说不行我搞不定\n然后就把他的学生送来\n小宋\n于是小宋就加入我们队\n刚开始一起\n所以宋涞下一场不要你师傅了\n就我俩好吧\n我们的和声\namani\n我会跟我会跟不停的人一直合作\n但是对我自己来说\n我南京这个乐队一直是一个乐队\n我这一次决定尝试新东西的时候\n我给大家写了个信\n我是把他们当家人\n跟我跟我一样\n只不过我需要点新鲜的东西\n因为我已经这么大了\n我想有些挑战\n哪怕被哪怕被黄毅骂\n我还得挑战\n我得挑战我自己\n我要去做些新东西\n所以阿玛尼也好\n包括包括朱格乐\n也包括袁铮\n我不知道他们怎么看\n反正我是把他们当兄弟家人一样\n所以基本基本上就是这样\n然后另外和声呢\n葛琪璘\n葛老师已经跟我合作了10年了\n但是她以前一直在幕后\n她是我们合声组的教练\n我的所有的歌都他写的\n然后呢喜欢合声呢\n叫合声三美去怎么唱怎么练\n所以每次演出的时候\n三美在台上\n葛老师就在旁边\n就听到了\n然后终于第一次可以上台\n谢谢葛老师\n啊这三位大家都知道啊\n万晓利\n藏鸿飞 张玮玮\n他们这一次都是\n你们也看到\n就是每一个人只有一两首歌\n甚至几个小节\n但是从排练到彩排\n到到每天的long down\n甚至在上台前各位还在练手风琴\n所以我特别感动\n这就是一个认真的职业的音乐人\n就是这个样子\n尤其是万晓利和张玮玮\n包括我们F4的另外一个狼哥\n虽然我我我号称我F4一员\n但他们三个\n呃怎么说呢\n就是基本上没有他们也就没有我\n然后他们一直带领我成长\n宽容我的错误\n然后鼓励我\n除了没给我借钱什么都干\n他们也没钱\n嗯就是老艺术家老艺人\n就这个态度\n藏鸿飞还亲自买了一个新的口风琴\n我要特别介绍我们的音乐总监周亮\n我们的所有的歌曲都是他编的\n他跟胡晨有点像\n都很年轻\n呃但是有天赋\n又他妈勤奋\n然后态度还好\n所以你说这样的人真的很难找\n哦上不去OK\n上不去没关系\n反正大家记住了\n反正名字嘛\n不重要就好像我名字也不重要\n主要看长相是吧\n我们的monitor调音师 李志宇\n志宇出来给他露个脸\n没事你出来露个脸露个脸\n还有我们的舞台助理杨洋小魏\n他们三个都是我们公司最好的员工\n小魏杨洋志宇\n好我们的调音师林子彧\n大家看不见\n呃我们是十号晚上\n在这边整个彩排了一遍\n然后录下来\n然后每天早晨\n子彧跟周亮就会过来跟着音频\n就一边放音频一边重新调\n怎样把每个音色做到最所谓的极致\n所以他们非常非常辛苦\n而且紫玉他还不是科班出身\n但是我跟我是哎\n你反正我我跟他合作之后\n我就不想再换其他人了\n哎反正反正很厉害就是好吧\n过来过来\n灯光师早川凌子\n早老师特别不喜欢\n我介绍他也不希望我表扬她\n早老师就是我的\n是我的监委\n只要我演的好\n他什么苦他都会笑出来\n只要只要我演的差\n我给他再多钱他都不看我\n所以每次我在台上\n我想散个德行的时候\n我想到早老师失望的眼神\n真的\n我就OK控制住\nVJ\n贺敬如小贺我们也是10年前开始合作\n一开始他是在一家公司帮我们做\n后来慢慢的他自己厉害了\n开始单干\n现在开始接了很多活\n但是我们已经长时间没有一起做了\n尤其我去年的演出我都没有做视频\n这场演出是因为有这些屏\n所以才决定做视觉\n然后临时找了小贺\n然后他手上有很多活\n都是他匆匆的来帮我处理这些事情\n到现在我就见过他一面\n还在路上碰到他\n在亚罗街\n今天的总导演小德李建德\n小德希望今天的演出你能够满意\n谢谢\n我们整个的呃导播\n纪录片都是来自南京的一个公司\n叫for why\n他在南京也是一直跟我们合作\n然后他们二三十个人我就不报名字了\n反正队伍很长\n谢谢还有\n这次特别的一个工作人员\n就是我们的导播Peter\n来台湾的Peter老师\n你们看到的东西都是Peter老师\n他要决定放放\n差不多这样吧\n呃我再最后说两句啊\n第一个回去呢\n可能打车比较难打\n大家一定要注意秩序\n不要影响别人\n因为周围还有居民\n第二个好好生活",
