    "lyrics": "春末的南方城市\n2025叁缺壹吉隆坡站\n这个下雨的清晨\n我从南方的这个城市准备去南方的那个城市\n我和我的兄弟在一家包子铺门口分手赶往远处的站台\n车上的白领睡意朦胧隔着眼屎看着我\n这让人心慌 这让人心慌\n这让人心慌 这让人心慌\n这个下雨的清晨\n我从城市的这头渡过河去城市的那头\n街上的红灯绿灯闪烁不停闪烁不停闪烁\n这让人心慌\n兄弟在玻璃的建筑里 我在潮湿的路上\n人们重复着重复着重复着重复着重复\n这让人心慌 这让人心慌\n不知道有谁能让你诉说\n你这样的生活到底为了什么\n我看见你靠在窗口沉默\n路过了青春我们还拥有什么\n这让人心慌 这让人心慌\n这让人心慌 这让人心慌\n不知道有谁能让你诉说\n你这样的生活到底为了什么\n我看见你靠在窗口沉默\n路过了青春我们还拥有什么\n这让人心慌 这让人心慌",
