    "quote": "有多少瞬间，有多少悔恨，她，究竟是谁。",
    "lyrics": "秋天的老狼\n2025叁缺壹吉隆坡站\n夜，浓雾渐升\n越来越遥远，城市的灯\n一个人，冰冷的嘴唇\n远处传来谁的哭声\n嗨，这秋天的早晨\n有多少瞬间，有多少悔恨\n她，究竟是谁\n为何是我们之间的堡垒\n我的爱，是什么颜色\n我和你又会成为什么颜色\n走吧，走到铁桥的对面\n那里有我们过去的纯真\n啦~~~啦~~~",
