    "lyrics": "兄弟从伊斯坦布尔给我带来六英镑\n他说在这个世界上\n没有它不能买到的东西\n不是我不相信你啊兄弟\n不是我不相信这六英镑\n只是你知道的那些过去\n只是你不知道的那些过去\n昨天我从街头的拐角\n看见一家猪头店\n那个戴D杯罩的女人说\n你想要什么就对我说\n我说老板 一斤尊严要多少钱\n我说老板 一斤理想要多少钱\n我说老板 一斤坚持要多少钱\n我说老板 一斤纯粹要多少钱\n我说朋友 一斤爱情要多少钱\n我说宝贝 一斤欲望要多少钱\n我说兄弟 一斤婚姻要多少钱\n我说老板 一斤理想要多少钱\n我说朋友 一斤爱情要多少钱\n我说宝贝 一斤欲望要多少钱\n我说兄弟 一斤婚姻要多少钱\n我说老板 一斤理想要多少钱\n我说朋友 一斤爱情要多少钱\n我说宝贝 一斤欲望要多少钱\n我说兄弟 一斤婚姻要多少钱\n我说老板 一斤理想要多少钱",
